"use client";

import { motion, useReducedMotion } from "framer-motion";

const MEDALLION = 64;
const HALF = MEDALLION / 2;
const PARTICLE_ANGLES = [-70, -25, 20, 65, 110, 155, 205, 250] as const;

function SuccessParticles() {
  return (
    <>
      {PARTICLE_ANGLES.map((deg, i) => {
        const rad = (deg * Math.PI) / 180;
        const distance = 30 + (i % 3) * 8;
        return (
          <motion.span
            key={deg}
            aria-hidden
            className="absolute h-1.5 w-1.5 rounded-full bg-emerald-400"
            style={{ top: "50%", left: "50%", marginLeft: -3, marginTop: -3 }}
            initial={{ x: 0, y: 0, opacity: 1, scale: 1 }}
            animate={{ x: Math.cos(rad) * distance, y: Math.sin(rad) * distance, opacity: 0, scale: 0.3 }}
            transition={{ duration: 0.65, delay: 0.15 + (i % 3) * 0.03, ease: [0.16, 1, 0.3, 1] }}
          />
        );
      })}
    </>
  );
}

export function SuccessState({
  title,
  description,
  action,
}: {
  title: string;
  description: string;
  action?: { label: string; onClick?: () => void };
}) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <div className="relative flex w-full flex-col items-center gap-4 overflow-hidden rounded-2xl border border-slate-200 bg-white px-8 py-10 text-center dark:border-slate-700 dark:bg-neutral-950">
      <motion.span
        aria-hidden
        className="absolute inset-x-0 top-0 h-0.5 bg-emerald-500"
        initial={{ scaleX: 0 }}
        animate={{ scaleX: 1 }}
        transition={{ duration: 0.5, ease: [0.16, 1, 0.3, 1] }}
        style={{ transformOrigin: "center" }}
      />

      <div className="relative flex items-center justify-center" style={{ width: MEDALLION, height: MEDALLION }}>
        {/* halo: a one-shot confirm flash, not a loop, since a resolved state shouldn't keep animating */}
        <motion.span
          aria-hidden
          className="absolute inset-0 rounded-full blur-md bg-emerald-400/30 dark:bg-emerald-400/20"
          initial={{ opacity: 0 }}
          animate={shouldReduceMotion ? { opacity: 0.3 } : { opacity: [0, 0.55, 0.28] }}
          transition={shouldReduceMotion ? { duration: 0.2 } : { duration: 0.7, ease: [0.16, 1, 0.3, 1] }}
        />

        {!shouldReduceMotion && (
          <motion.span
            aria-hidden
            className="absolute rounded-full border-2 border-emerald-400/60"
            style={{
              width: MEDALLION,
              height: MEDALLION,
              top: "50%",
              left: "50%",
              marginLeft: -HALF,
              marginTop: -HALF,
            }}
            initial={{ scale: 0.6, opacity: 0.9 }}
            animate={{ scale: 1.9, opacity: 0 }}
            transition={{ duration: 0.7, ease: [0.16, 1, 0.3, 1] }}
          />
        )}
        {!shouldReduceMotion && <SuccessParticles />}

        <div
          className="relative flex items-center justify-center rounded-full border border-emerald-300 bg-emerald-50 text-emerald-500 dark:border-emerald-500/40 dark:bg-emerald-500/10 dark:text-emerald-400"
          style={{ width: MEDALLION, height: MEDALLION }}
        >
          <svg viewBox="0 0 24 24" width="30" height="30" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden>
            <motion.circle
              cx="12"
              cy="12"
              r="9"
              initial={{ scale: 0.6, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              transition={shouldReduceMotion ? { duration: 0.2 } : { type: "spring", stiffness: 350, damping: 20 }}
            />
            <motion.path
              d="M8 12.5l2.5 2.5L16 9.5"
              initial={{ pathLength: 0, opacity: 0 }}
              animate={{ pathLength: 1, opacity: 1 }}
              transition={shouldReduceMotion ? { duration: 0 } : { duration: 0.5, delay: 0.25, ease: [0.22, 1, 0.36, 1] }}
            />
          </svg>
        </div>
      </div>

      <div className="flex flex-col gap-1.5">
        <h3 className="text-base font-semibold text-slate-900 dark:text-white">{title}</h3>
        <p className="text-sm leading-relaxed text-slate-500 dark:text-slate-400">{description}</p>
      </div>

      {action && (
        <motion.button
          onClick={action.onClick}
          whileHover={shouldReduceMotion ? undefined : { y: -2 }}
          whileTap={{ scale: 0.96, y: 0 }}
          transition={{ type: "spring", stiffness: 500, damping: 30 }}
          className="group relative mt-1 inline-flex items-center justify-center overflow-hidden rounded-lg bg-emerald-700 px-4 py-2 text-sm font-medium text-white shadow-[0_1px_2px_rgba(4,120,87,0.3)] transition-[box-shadow,background-color] duration-300 hover:bg-emerald-600 hover:shadow-[0_10px_20px_-8px_rgba(4,120,87,0.6)] focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-emerald-700"
        >
          <span
            aria-hidden
            className="pointer-events-none absolute inset-0 -translate-x-full bg-gradient-to-r from-transparent via-white/30 to-transparent transition-transform duration-700 ease-out group-hover:translate-x-full motion-reduce:hidden"
          />
          <span className="relative">{action.label}</span>
        </motion.button>
      )}
    </div>
  );
}
